package com.landportal.entity;
import jakarta.persistence.*;
@Entity @Table(name="parcels") public class Parcel { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String surveyNumber; @Column(nullable=false) String district,village; double area; Double latitude,longitude; public Long getId(){return id;} public String getSurveyNumber(){return surveyNumber;} public void setSurveyNumber(String v){surveyNumber=v;} public String getDistrict(){return district;} public void setDistrict(String v){district=v;} public String getVillage(){return village;} public void setVillage(String v){village=v;} public double getArea(){return area;} public void setArea(double v){area=v;} public Double getLatitude(){return latitude;} public void setLatitude(Double v){latitude=v;} public Double getLongitude(){return longitude;} public void setLongitude(Double v){longitude=v;} }
